<?php require_once __DIR__.'/../config/config.php'; require_once __DIR__.'/../config/auth.php'; require_login(); $id=(int)($_GET['id']??0); $st=$pdo->prepare('SELECT * FROM dokumen WHERE id=?');$st->execute([$id]);$d=$st->fetch(); if(!$d) die('Dokumen tidak ditemukan'); $ext=strtolower(pathinfo($d['filename'],PATHINFO_EXTENSION)); $url='/MRMIKIT/uploads/'.rawurlencode($d['filename']); require __DIR__.'/../partials/header.php'; ?><h2><?=htmlspecialchars($d['nama'])?></h2><div class="mb-3 text-muted"><?=htmlspecialchars($d['kategori'])?> · Versi <?=htmlspecialchars($d['versi'])?></div><?php if($ext==='pdf'):?><iframe src="<?=$url?>" style="width:100%;height:75vh;border:1px solid #ddd"></iframe><?php else:?><a class="btn btn-success" target="_blank" href="<?=$url?>">Buka / Download File</a><?php endif;?><?php require __DIR__.'/../partials/footer.php';